class JambaJEPAAgent(nn.Module):
    def __init__(self, layers, jepa_dim):
        self.layers = nn.ModuleList(layers)  # Attention, Mamba, and optional MoE layers
        self.projector = nn.Linear(layers[-1].d_model, jepa_dim)
        self.predictor = nn.Sequential(nn.Linear(jepa_dim, jepa_dim), nn.GELU(), nn.Linear(jepa_dim, jepa_dim))
        self.workflow = WorkflowController()
    def encode(self, tokens):
        x = embed(tokens)
        for layer in self.layers:
            x = layer(x)
        return x
    def forward(self, task, tokens, target_tokens=None):
        x = self.encode(tokens)
        action_plan = self.workflow.plan(task, state=x[:, -1])
        token_logits = lm_head(x)
        z_pred = self.predictor(self.projector(x))
        loss_jepa = latent_mse(z_pred, stopgrad(target_latents(target_tokens))) if target_tokens is not None else 0
        return token_logits, action_plan, {"jepa_loss": loss_jepa}
def eval_hook(out): return {"ppl": ppl(out), "latent_mse": out["jepa_loss"], "task_success": score_plan(out)}

class EdgeMultimodalAdapter(nn.Module):
    def __init__(self, mobile_lm, vision_encoder, rank=8):
        self.mobile_lm = freeze(mobile_lm)
        self.vision = freeze_or_tune(vision_encoder)
        self.proj = nn.Linear(self.vision.width, self.mobile_lm.d_model)
        self.lora = attach_lora(self.mobile_lm, rank=rank)
        self.ocr_head = nn.Linear(self.mobile_lm.d_model, vocab_size)
        self.box_head = nn.Linear(self.mobile_lm.d_model, 4)
    def forward(self, image, text_tokens):
        v = self.proj(self.vision(image))
        x = concat(v, embed(text_tokens))
        h = self.mobile_lm(x, adapters=self.lora)
        return {"logits": lm_head(h), "ocr": self.ocr_head(h), "boxes": self.box_head(h)}
def eval_hook(batch, out): return metrics(out, ["ocr_f1","box_iou","vqa_acc","latency_ms","peak_ram_mb"])
